func TestProviderBlocksAmbientTenantCredentialAtCustomEndpoint(t *testing.T) {
	for _, tc := range []struct {
		name     string
		hasAdmin bool
	}{
		{name: "tenant credential alone"},
		{name: "admin credential still works", hasAdmin: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			attributes := map[string]tftypes.Value{
				"tenant_base_url": tftypes.NewValue(tftypes.String, "http://127.0.0.1:8080/v1"),
			}
			if tc.hasAdmin {
				attributes["admin_api_key"] = tftypes.NewValue(tftypes.String, "sk-admin-synthetic")
			}
			response := configureProviderWithAttributeValues(t, "", false, attributes, map[string]string{
				"OPENAI_TENANT_ADMIN_KEY": "sk-tenant-ambient-synthetic",
			})
			if !tc.hasAdmin {
				if !response.Diagnostics.HasError() || response.ResourceData != nil || response.DataSourceData != nil {
					t.Fatal("provider accepted configuration with only an ambient tenant credential at a custom endpoint")
				}
				return
			}
			if response.Diagnostics.HasError() {
				t.Fatalf("provider rejected its separately configured admin credential: %v", response.Diagnostics)
			}
			data, ok := response.ResourceData.(*openaiapi.ProviderData)
			if !ok {
				t.Fatalf("provider data has unexpected type %T", response.ResourceData)
			}
			if _, ok := data.Client("admin"); !ok {
				t.Fatal("provider data is missing the separately configured admin audience")
			}
			if _, ok := data.Client("tenant"); ok {
				t.Fatal("provider accepted an ambient tenant credential at a custom endpoint")
			}
		})
	}
}
